<?php
require_once __DIR__ . '/../config/db.php';require_once __DIR__ . '/../services/userService.php';require_once __DIR__ . '/../includes/auth.php';$pdo=openDatabase();$actor=requireLogin($pdo);requireRole($actor,array('Administrator'));$id=filter_input(INPUT_GET,'user_id',FILTER_VALIDATE_INT);if(!$id||$id<1){http_response_code(400);exit('Invalid user ID');}$target=findUserById($pdo,$id);if(!$target){http_response_code(404);exit('Account not found');}$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken($_POST);try{$action=isset($_POST['action'])?$_POST['action']:'';if($action==='role'){changeUserRole($pdo,(int)$actor['user_id'],$id,(string)$_POST['role']);$success='Role updated.';}elseif($action==='status'){changeUserStatus($pdo,(int)$actor['user_id'],$id,(string)$_POST['status']);$success='Status updated.';}elseif($action==='delete'){removeUserAccount($pdo,(int)$actor['user_id'],$id);header('Location: manage-users.php?deleted=1',true,303);exit;}else{throw new InvalidArgumentException('Invalid action.');}$target=findUserById($pdo,$id);}catch(InvalidArgumentException $e){$error=$e->getMessage();}}
require __DIR__ . '/../includes/header.php';require __DIR__ . '/../includes/nav.php';?><main class="container py-4"><h1>Manage account</h1><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=$success?></div><?php endif;?><dl><dt>Name</dt><dd><?=htmlspecialchars($target['full_name'],ENT_QUOTES,'UTF-8')?></dd><dt>Email</dt><dd><?=htmlspecialchars($target['email'],ENT_QUOTES,'UTF-8')?></dd></dl><form method="post" class="mb-3"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="role"><label class="form-label">Role</label><select class="form-select mb-2" name="role"><?php foreach(userRoles() as $v):?><option <?=$target['role']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn btn-primary">Save role</button></form><form method="post" class="mb-3"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="status"><label class="form-label">Status</label><select class="form-select mb-2" name="status"><?php foreach(userStatuses() as $v):?><option <?=$target['status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn btn-warning">Save status</button></form><form method="post" onsubmit="return confirm('Delete this account? Related tutoring requests block deletion.');"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger">Delete account</button></form><p class="mt-3"><a href="manage-users.php">Back to users</a></p></main><?php require __DIR__ . '/../includes/footer.php'; ?>
